DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM modules m JOIN topics t ON t.id=m.topic_id JOIN subtests s ON s.id=t.subtest_id WHERE s.code IN ('PU','PPU','PBM','PK','LBI','LBE','PM') AND t.code LIKE 'materi:%' AND NOT EXISTS (SELECT 1 FROM _materi_order e WHERE e.code=m.code AND e.subject_code=s.code AND e.topic_code=t.code)) THEN
    RAISE EXCEPTION 'Evidence-backed Materi recovery refuses unknown or cross-assigned module';
  END IF;
END $$;

WITH target AS (SELECT m.id, row_number() over(order by e.subject_code,e.order_key,e.code) temp_rank, max(abs(m.sequence_no)) over() max_abs, count(*) over() total FROM modules m JOIN topics t ON t.id=m.topic_id JOIN subtests s ON s.id=t.subtest_id JOIN _materi_order e ON e.code=m.code AND e.subject_code=s.code AND e.topic_code=t.code)
UPDATE modules m SET sequence_no=target.max_abs+target.total+target.temp_rank FROM target WHERE m.id=target.id;
WITH ranked AS (SELECT m.id,row_number() over(partition by e.subject_code order by e.order_key,e.code)::int sequence_no FROM modules m JOIN topics t ON t.id=m.topic_id JOIN subtests s ON s.id=t.subtest_id JOIN _materi_order e ON e.code=m.code AND e.subject_code=s.code AND e.topic_code=t.code)
UPDATE modules m SET sequence_no=ranked.sequence_no FROM ranked WHERE m.id=ranked.id;
